	private static Object rawQuadSink(Class<?> sinkType, List<long[]> rows) {
		return rawQuadSink(sinkType, rows, () -> {
		});
	}

	private static Object rawQuadSink(Class<?> sinkType, List<long[]> rows, Runnable callback) {
		return Proxy.newProxyInstance(sinkType.getClassLoader(), new Class<?>[] { sinkType }, (proxy, method, args) -> {
			if ("accept".equals(method.getName())) {
				rows.add(new long[] { (long) args[0], (long) args[1], (long) args[2], (long) args[3] });
				callback.run();
				return null;
			}
			throw new AssertionError("Unexpected RawQuadSink method: " + method);
		});
	}

	private static final class LockAwareCursorStepTripleStore extends TripleStore {

		private int lockAwareStepCalls;

		private LockAwareCursorStepTripleStore(File dataDir) throws IOException {
			super(dataDir, new LmdbStoreConfig("spoc,posc"), null);
		}

		@Override
		public RecordIterator getTriples(TxnManager.Txn txn, long subj, long pred, long obj, long context,
				boolean explicit) {
			return new RecordIterator() {

				private final long[] row = { 11L, 22L, 33L, 44L };
				private boolean emitted;

				@Override
				public long[] next() {
					throw new AssertionError(
							"Frontier scan must not reacquire the transaction read lock through RecordIterator.next()");
				}

				public long[] nextWithTxnReadLockHeld() {
					assertTrue(LockAwareCursorStepTripleStore.this.getTxnManager()
							.lockManager()
							.isReaderActive(),
							"Frontier source must hold the transaction read lock during cursor step");
					lockAwareStepCalls++;
					if (emitted) {
						return null;
					}
					emitted = true;
					return row;
				}

				@Override
				public void close() {
				}
			};
		}

		private int lockAwareStepCalls() {
			return lockAwareStepCalls;
		}
	}

	private static final class CloseLockObservingTripleStore extends TripleStore {

		private final AtomicBoolean iteratorCloseCalled = new AtomicBoolean();
		private final AtomicBoolean iteratorCloseAcquiredWriteLock = new AtomicBoolean();

		private CloseLockObservingTripleStore(File dataDir) throws IOException {
			super(dataDir, new LmdbStoreConfig("spoc,posc"), null);
		}

		@Override
		public RecordIterator getTriples(TxnManager.Txn txn, long subj, long pred, long obj, long context,
				boolean explicit) {
			return new RecordIterator() {

				private final long[] row = { 11L, 22L, 33L, 44L };
				private boolean emitted;
				private boolean closed;

				@Override
				public long[] next() {
					if (emitted) {
						return null;
					}
					emitted = true;
					return row;
				}

				@Override
				public void close() {
					if (closed) {
						return;
					}
					closed = true;
					iteratorCloseCalled.set(true);
					long writeStamp = CloseLockObservingTripleStore.this.getTxnManager().lockManager().tryWriteLock();
					iteratorCloseAcquiredWriteLock.set(writeStamp != 0L);
					if (writeStamp != 0L) {
						CloseLockObservingTripleStore.this.getTxnManager().lockManager().unlockWrite(writeStamp);
					}
				}
			};
		}

		private boolean iteratorCloseCalled() {
			return iteratorCloseCalled.get();
		}

		private boolean iteratorCloseAcquiredWriteLock() {
			return iteratorCloseAcquiredWriteLock.get();
		}
	}

	private static final class CursorStepTripleStore extends TripleStore {

		private final CursorStepRenewal renewal;

		private CursorStepTripleStore(File dataDir, CursorStepRenewal renewal) throws IOException {
			super(dataDir, new LmdbStoreConfig("spoc,posc"), null);
			this.renewal = renewal;
		}

		@Override
		public RecordIterator getTriples(TxnManager.Txn txn, long subj, long pred, long obj, long context,
				boolean explicit) {
			return new RecordIterator() {

				private boolean stepped;

				@Override
				public long[] next() {
					if (stepped) {
						return null;
					}
					stepped = true;
					renewal.attemptInsideCursorStep();
					return null;
				}

				@Override
				public void close() {
				}
			};
		}
	}

	private static final class CursorStepRenewal implements AutoCloseable {

		private final CountDownLatch cursorStepEntered = new CountDownLatch(1);
		private final CountDownLatch attemptFinished = new CountDownLatch(1);
		private final ExecutorService executor = Executors.newSingleThreadExecutor();
		private final AtomicBoolean writeLockAcquired = new AtomicBoolean();
		private final AtomicBoolean completed = new AtomicBoolean();
		private Future<?> worker;

		private void start(TxnManager txnManager) {
			worker = executor.submit(() -> {
				assertTrue(cursorStepEntered.await(10, TimeUnit.SECONDS), "cursor step did not start");
				long writeStamp = txnManager.lockManager().tryWriteLock();
				writeLockAcquired.set(writeStamp != 0L);
				try {
					if (writeStamp != 0L) {
						txnManager.deactivate();
						txnManager.activate();
						completed.set(true);
					}
				} finally {
					if (writeStamp != 0L) {
						txnManager.lockManager().unlockWrite(writeStamp);
					}
					attemptFinished.countDown();
				}
				return null;
			});
		}

		private void attemptInsideCursorStep() {
			cursorStepEntered.countDown();
			try {
				assertTrue(attemptFinished.await(10, TimeUnit.SECONDS), "renewal attempt did not finish");
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new AssertionError("Interrupted while awaiting the cursor-step renewal attempt", e);
			}
		}

		private void awaitWorker() throws Exception {
			worker.get();
		}

		private boolean writeLockAcquired() {
			return writeLockAcquired.get();
		}

		private boolean completed() {
			return completed.get();
		}

		@Override
		public void close() {
			executor.shutdownNow();
		}
	}
